<?php
 namespace Pterodactyl\Jobs\Dezerx; use Throwable; use Illuminate\Support\Str; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Redis; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Contracts\Queue\ShouldBeEncrypted; use Pterodactyl\Services\Dezerx\Importer\Transfer; use Pterodactyl\Services\Dezerx\Importer\Credentials; use Pterodactyl\Services\Dezerx\Importer\RemoteConnection; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class ImportChunk extends Job implements ShouldQueue, ShouldBeEncrypted { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 10_800; public int $maxExceptions = 1; public function __construct( public Server $server, public ?int $hostProfile, public ?int $credentialProfile, public array $custom, public string $source, public string $destination, public string $mode, public array $files, public int $total, public string $chunkId = '', ) { if ($this->chunkId === '') { $this->chunkId = (string) Str::uuid(); } } public function handle(): void { $result = ['copied' => 0, 'skipped' => 0, 'failed' => count($this->files), 'bytes' => 0]; try { $credentials = Credentials::resolve($this->hostProfile, $this->credentialProfile, $this->custom, $this->source); if ($credentials !== null) { $result = $this->copy($credentials); } } catch (Throwable $exception) { report($exception); } $this->finish($result); } public function failed(?Throwable $exception): void { $this->finish(['copied' => 0, 'skipped' => 0, 'failed' => count($this->files), 'bytes' => 0]); } private function copy(Credentials $credentials): array { $client = RemoteConnection::for($credentials); $node = new ServerFiles($this->server); $seenSoFar = 0; try { $opened = $client->open(); if (!$opened['ok']) { return ['copied' => 0, 'skipped' => 0, 'failed' => count($this->files), 'bytes' => 0]; } return app(Transfer::class)->copyBatch( $this->server, $node, $client, $this->source, $this->destination, $this->mode, $this->files, function (string $message, int $current, int $total, int $bytes) use (&$seenSoFar) { $delta = $current - $seenSoFar; $seenSoFar = $current; $this->reportProgress($message, $delta); }, ); } finally { $client->close(); } } private function reportProgress(string $message, int $seenDelta): void { $key = ImportServer::chunkKey($this->server->uuid); $redis = Redis::connection(); if ($seenDelta > 0) { $redis->hincrby($key, 'seen', $seenDelta); } $seen = (int) $redis->hget($key, 'seen'); $bytes = (int) $redis->hget($key, 'bytes'); ImportServer::mark( $this->server->uuid, 'copying', $message, ['current' => $seen, 'total' => $this->total, 'bytes' => $bytes], ); } private function finish(array $result): void { $key = ImportServer::chunkKey($this->server->uuid); $doneKey = $key . ':done'; $redis = Redis::connection(); $firstTime = (bool) $redis->sadd($doneKey, $this->chunkId); $redis->expire($doneKey, $this->timeout + 300); if (!$firstTime) { return; } $redis->hincrby($key, 'copied', $result['copied']); $redis->hincrby($key, 'skipped', $result['skipped']); $redis->hincrby($key, 'failed', $result['failed']); $redis->hincrby($key, 'bytes', $result['bytes']); $remaining = $redis->hincrby($key, 'remaining', -1); if ($remaining > 0) { return; } $totals = [ 'copied' => (int) $redis->hget($key, 'copied'), 'skipped' => (int) $redis->hget($key, 'skipped'), 'failed' => (int) $redis->hget($key, 'failed'), 'bytes' => (int) $redis->hget($key, 'bytes'), ]; $redis->del($key, $doneKey); ImportServer::mark($this->server->uuid, 'done', ImportServer::summary($totals)); } } 